BEGIN
    UPDATE items SET parent_id = NULL, updated_at = clock_timestamp()
    WHERE parent_id IN (SELECT item_id FROM media_collections WHERE owner_id = OLD.id)
      AND id NOT IN (SELECT item_id FROM media_collections WHERE owner_id = OLD.id);
    DELETE FROM items WHERE id IN (
        SELECT item_id FROM media_collections WHERE owner_id = OLD.id
    );
    RETURN OLD;
END;

DECLARE original text := goby_sort_fold(COALESCE(name,''));
        candidate text;
        word text;
        remaining text;
        whitespace text := U&'\0009\000A\000B\000C\000D\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000';
BEGIN
    candidate := btrim(original,whitespace);
    FOREACH word IN ARRAY words LOOP
        IF left(candidate,char_length(word))=goby_sort_fold(word)
           AND char_length(candidate)>char_length(word)
           AND strpos(whitespace,substr(candidate,char_length(word)+1,1))>0 THEN
            remaining := btrim(substr(candidate,char_length(word)+1),whitespace);
            IF remaining<>'' THEN RETURN remaining; END IF;
        END IF;
    END LOOP;
    RETURN original;
END

DECLARE next_sequence bigint;
BEGIN
    PERFORM id FROM notification_transport WHERE id=1 FOR SHARE;
    PERFORM id FROM notification_journal_state WHERE id=1 FOR UPDATE;
    IF NOT EXISTS(SELECT 1 FROM notification_transport WHERE id=1 AND enabled)
       OR NOT EXISTS(SELECT 1 FROM notification_registrations r JOIN sessions s ON s.id=r.session_id JOIN users u ON u.id=r.user_id
         WHERE r.enabled AND s.kind='emby' AND s.user_id=r.user_id AND s.revoked_at IS NULL AND s.expires_at>clock_timestamp()
         AND NOT u.is_disabled AND p_kind=ANY(r.event_ids) AND (p_user IS NULL OR r.user_id=p_user)) THEN RETURN; END IF;
    IF p_kind='CatalogInvalidated' AND p_resync AND jsonb_array_length(p_refs)=0 THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='notification_source_scope_required';
    END IF;
    DELETE FROM notification_source_events WHERE sequence <= COALESCE((SELECT min(source_cursor) FROM notification_registrations WHERE enabled),9223372036854775807);
    IF octet_length(p_refs::text)>524288 OR jsonb_array_length(p_refs)>4096 OR
       (NOT EXISTS(SELECT 1 FROM notification_source_events WHERE id=p_id) AND (SELECT count(*) FROM notification_source_events)>=512) OR
        (SELECT COALESCE(sum(octet_length(refs::text)),0) FROM notification_source_events WHERE id<>p_id)+octet_length(p_refs::text)>4194304 THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='notification_source_capacity';
    END IF;
    UPDATE notification_journal_state SET sequence=sequence+1 WHERE id=1 RETURNING sequence INTO next_sequence;
    INSERT INTO notification_source_events(id,sequence,kind,user_id,refs,recursive,resync)
    VALUES(p_id,next_sequence,p_kind,p_user,p_refs,p_recursive,p_resync)
    ON CONFLICT(id) DO UPDATE SET sequence=EXCLUDED.sequence,refs=EXCLUDED.refs,recursive=EXCLUDED.recursive,resync=EXCLUDED.resync;
END

DECLARE word text;
        seen text[] := '{}';
        whitespace text := U&'\0009\000A\000B\000C\000D\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000';
BEGIN
    IF words IS NULL OR cardinality(words)>32 THEN RETURN false; END IF;
    IF cardinality(words)>0 AND (array_ndims(words)<>1 OR array_lower(words,1)<>1) THEN RETURN false; END IF;
    IF array_position(words,NULL) IS NOT NULL THEN RETURN false; END IF;
    FOREACH word IN ARRAY words LOOP
        IF octet_length(word) NOT BETWEEN 1 AND 128 OR translate(word,U&'\0001\0002\0003\0004\0005\0006\0007\0008\0009\000A\000B\000C\000D\000E\000F\0010\0011\0012\0013\0014\0015\0016\0017\0018\0019\001A\001B\001C\001D\001E\001F\007F\0080\0081\0082\0083\0084\0085\0086\0087\0088\0089\008A\008B\008C\008D\008E\008F\0090\0091\0092\0093\0094\0095\0096\0097\0098\0099\009A\009B\009C\009D\009E\009F','')<>word
           OR translate(word,whitespace,'')<>word OR goby_sort_fold(word)=ANY(seen) THEN RETURN false; END IF;
        seen := array_append(seen,goby_sort_fold(word));
    END LOOP;
    RETURN true;
END

BEGIN
    IF NEW.publication_phase NOT IN ('prepared', 'catalog_committed') THEN
        RETURN NEW;
    END IF;
    IF NEW.item_id IS DISTINCT FROM NEW.source_item_id
       OR NEW.library_id IS DISTINCT FROM NEW.source_library_id
       OR NEW.root_id IS DISTINCT FROM NEW.source_root_id THEN
        RAISE EXCEPTION 'media publication requires its live source owners' USING ERRCODE = '55000';
    END IF;
    -- A retained reservation may advance even after the catalog commit. It
    -- must not be admitted again or conflict with its own publication journal.
    IF TG_OP = 'UPDATE' AND OLD.publication_phase IN ('prepared', 'catalog_committed') THEN
        RETURN NEW;
    END IF;
    PERFORM id FROM libraries WHERE id = NEW.source_library_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'media publication library is unavailable' USING ERRCODE = '55000';
    END IF;
    PERFORM id FROM library_roots
        WHERE id = NEW.source_root_id AND library_id = NEW.source_library_id FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'media publication root is unavailable' USING ERRCODE = '55000';
    END IF;
    PERFORM id FROM items
        WHERE id = NEW.source_item_id AND library_id = NEW.source_library_id
          AND root_id = NEW.source_root_id FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'media publication item is unavailable' USING ERRCODE = '55000';
    END IF;
    IF EXISTS (SELECT 1 FROM scan_jobs
               WHERE library_id = NEW.source_library_id AND status IN ('Queued', 'Running')) THEN
        RAISE EXCEPTION 'a scan is active for the media publication library' USING ERRCODE = '55000';
    END IF;
    IF EXISTS (SELECT 1 FROM media_deletion_operations WHERE library_id = NEW.source_library_id) THEN
        RAISE EXCEPTION 'media deletion recovery is pending for this library' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;

BEGIN
    PERFORM id FROM libraries WHERE id = NEW.library_id FOR KEY SHARE;
    IF EXISTS (SELECT 1 FROM media_operations
               WHERE source_library_id = NEW.library_id
                 AND publication_phase IN ('prepared', 'catalog_committed')) THEN
        RAISE EXCEPTION 'media publication recovery is pending for this library' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;

BEGIN
    IF TG_TABLE_NAME = 'library_roots' THEN
        IF EXISTS (SELECT 1 FROM media_operations
                   WHERE source_root_id = OLD.id
                     AND publication_phase IN ('prepared', 'catalog_committed')) THEN
            RAISE EXCEPTION 'media publication recovery is pending for this root' USING ERRCODE = '55000';
        END IF;
    ELSIF TG_TABLE_NAME = 'items' THEN
        IF EXISTS (SELECT 1 FROM media_operations
                   WHERE source_item_id = OLD.id
                     AND publication_phase IN ('prepared', 'catalog_committed')) THEN
            RAISE EXCEPTION 'media publication recovery is pending for this item' USING ERRCODE = '55000';
        END IF;
    ELSIF TG_TABLE_NAME = 'libraries' THEN
        IF EXISTS (SELECT 1 FROM media_operations
                   WHERE source_library_id = OLD.id
                     AND publication_phase IN ('prepared', 'catalog_committed')) THEN
            RAISE EXCEPTION 'media publication recovery is pending for this library' USING ERRCODE = '55000';
        END IF;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;

BEGIN
    IF EXISTS (SELECT 1 FROM media_deletion_operations WHERE root_id = OLD.id) THEN
        RAISE EXCEPTION 'media deletion recovery is pending for this root' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;

BEGIN
    IF NEW.status IN ('Queued', 'Running') THEN
        PERFORM id FROM libraries WHERE id = NEW.library_id FOR KEY SHARE;
        IF EXISTS (SELECT 1 FROM media_deletion_operations WHERE library_id = NEW.library_id) THEN
            RAISE EXCEPTION 'media deletion recovery is pending for this library' USING ERRCODE = '55000';
        END IF;
    END IF;
    RETURN NEW;
END;

BEGIN
    IF NEW.status IN ('Queued', 'Running') THEN
        PERFORM id FROM libraries WHERE id = NEW.library_id FOR KEY SHARE;
        IF EXISTS (SELECT 1 FROM media_operations
                   WHERE source_library_id = NEW.library_id
                     AND publication_phase IN ('prepared', 'catalog_committed')) THEN
            RAISE EXCEPTION 'media publication recovery is pending for this library' USING ERRCODE = '55000';
        END IF;
    END IF;
    RETURN NEW;
END;

BEGIN
    NEW.normalized_hash := sha256(convert_to(lower(btrim(NEW.name)), 'UTF8'));
    RETURN NEW;
END;
